import requests
import json

url = "https://partner.shopeemobile.com/api/v2/logistics/set_mart_packaging_info?access_token=access_token&partner_id=partner_id&shop_id=shop_id&sign=sign&timestamp=timestamp"

payload=json.dumps({
  "dimension": {
    "height": 15,
    "length": 15,
    "width": 15
  },
  "enable": True,
  "packaging_fee": {
    "value": 100.00
  }
})
headers = {
  'Content-Type': 'application/json'
}
response = requests.RPCRequest("POST",url,headers=headers, data=payload, allow_redirects=False)

print(response.text)
